def test_break_axis_invalid_axis_raises():
    """BreakAxis with axis not 'x' or 'y' raises ValueError.

    Targets structural.py __post_init__ line 65.
    """
    with pytest.raises(ValueError, match="'x' or 'y'"):
        BreakAxis(axis="z", gap=(1, 2))


def test_break_axis_invalid_style_raises():
    """BreakAxis with unknown break_style raises ValueError.

    Targets structural.py __post_init__ line 68.
    """
    with pytest.raises(ValueError, match="break_style"):
        BreakAxis(axis="y", gap=(1, 2), break_style="dots")


def test_break_axis_multiple_gaps_serializes():
    """BreakAxis with multiple gap pairs serializes correctly.

    Targets _render.py _serialize_structural gap normalization (lines 311-320).
    """
    ba = BreakAxis(axis="y", gap=[(10, 20), (40, 50)])
    from ferrum._render import _RenderMixin

    d = _RenderMixin._serialize_structural(ba)
    assert d["type"] == "break_axis"
    assert len(d["gaps"]) == 2
    assert d["gaps"][0] == [10, 20]
    assert d["gaps"][1] == [40, 50]


def test_break_axis_single_gap_tuple_normalized():
    """BreakAxis with a single (start, end) gap normalizes to [[start, end]].

    Targets _render.py _serialize_structural lines 313-318.
    """
    ba = BreakAxis(axis="x", gap=(5, 15))
    from ferrum._render import _RenderMixin

    d = _RenderMixin._serialize_structural(ba)
    assert d["gaps"] == [[5, 15]]


