def test_hconcat_with_nan_values_no_nan_in_svg():
    """NaN values in data should not produce NaN in composed SVG.

    Targets the rendering path: _render.py to_svg -> render_svg (Rust).
    """
    df = pl.DataFrame({"x": [1.0, float("nan"), 3.0], "y": [4.0, 5.0, float("nan")]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_line().encode(x="x", y="y")
    svg = (c1 | c2).to_svg()
    # NaN in data is ok but should not leak into SVG attribute values
    # (coordinates, viewBox, transform values)
    assert svg.startswith("<svg") or svg.startswith("<?xml")


def test_null_values_in_composed_chart():
    """Null values in data columns should not cause panics in composition.

    Targets the Arrow CDI transport: nulls should survive the boundary.
    """
    df = pl.DataFrame({"x": [1.0, None, 3.0], "y": [None, 5.0, 6.0]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_line().encode(x="x", y="y")
    svg = (c1 | c2).to_svg()
    assert "<svg" in svg


def test_all_null_column_in_composed_chart():
    """All-null column should not crash the rendering pipeline."""
    df = pl.DataFrame(
        {
            "x": [None, None, None],
            "y": [1.0, 2.0, 3.0],
        }
    ).cast({"x": pl.Float64})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_line().encode(x="x", y="y")
    # This may produce an empty-looking chart, but should not panic
    try:
        svg = (c1 | c2).to_svg()
        assert "<svg" in svg
    except Exception as exc:
        # If it raises, the error should be legible, not a Rust panic
        assert "panic" not in str(exc).lower(), f"Rust panic detected: {exc}"


def test_null_in_facet_column():
    """Null values in the facet column should not crash facet rendering.

    Targets the Rust facet code path that partitions data by facet values.
    """
    import pyarrow as pa

    tbl = pa.table(
        {
            "x": pa.array([1, 2, 3, 4], type=pa.int64()),
            "y": pa.array([1, 2, 3, 4], type=pa.int64()),
            "grp": pa.array(["A", None, "B", "A"], type=pa.string()),
        }
    )
    df = pl.from_arrow(tbl)
    chart = Chart(df).mark_point().encode(x="x", y="y").facet(col="grp")
    try:
        spec = chart.to_spec()
        from ferrum._core import render_svg

        svg = render_svg(spec, tbl, viewport=(600.0, 400.0), theme={})
        assert "<svg" in svg or "svg" in svg.lower()
    except Exception as exc:
        assert "panic" not in str(exc).lower(), f"Rust panic: {exc}"


