def test_integer_columns_in_composed_chart():
    """Integer columns (not float) in composed charts should render fine.

    Targets Arrow CDI type handling: i64 columns vs f64 expectations.
    """
    df = pl.DataFrame({"x": [1, 2, 3], "y": [4, 5, 6]})
    assert df["x"].dtype == pl.Int64
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    svg = (c1 | c2).to_svg()
    _assert_valid_svg(svg)


def test_boolean_column_as_encoding():
    """Boolean column used as encoding should not crash."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "flag": [True, False, True]})
    c = Chart(df).mark_point().encode(x="x", y="flag")
    try:
        svg = c.to_svg()
        assert "<svg" in svg
    except Exception as exc:
        assert "panic" not in str(exc).lower(), f"Rust panic: {exc}"


def test_mixed_type_columns_in_layer():
    """Layering charts with different column types (int vs float) via +.

    The + operator does diagonal concat which may need type coercion.
    """
    df1 = pl.DataFrame({"x": [1, 2, 3], "y": [4, 5, 6]})  # Int64
    df2 = pl.DataFrame({"x": [1.5, 2.5, 3.5], "y": [4.5, 5.5, 6.5]})  # Float64
    c1 = Chart(df1).mark_point().encode(x="x", y="y")
    c2 = Chart(df2).mark_line().encode(x="x", y="y")
    layered = c1 + c2
    svg = layered.to_svg()
    _assert_valid_svg(svg)


