def test_repeat_chart_diagonal_cells_use_diagonal_template():
    """RepeatChart with diagonal should use diagonal template on matching cells.

    Targets RepeatChart._make_panel lines 786-790: use_diagonal check.
    """
    df = pl.DataFrame({"a": [1.0, 2.0], "b": [3.0, 4.0]})
    template = Chart(df).encode(x=fr.Repeat.column, y=fr.Repeat.row).mark_point()
    diag = Chart(df).mark_line().encode(x="a", y="a")
    rc = RepeatChart(template, row=["a", "b"], column=["a", "b"], diagonal=diag)
    cells = rc.expand()
    # Find diagonal cell (a, a) - it should use the diagonal template
    diag_cells = [(r, c, ch) for r, c, ch in cells if r == c]
    assert len(diag_cells) == 2  # (a,a) and (b,b)
    # Off-diagonal (a,b) should use the regular template
    off_diag = [(r, c, ch) for r, c, ch in cells if r != c]
    assert len(off_diag) == 2  # (a,b) and (b,a)


